import subprocess,os,time,base64,io,tarfile,threading,signal,glob,datetime,json
W='/kaggle/working';os.makedirs(W+'/logs',exist_ok=True)
F={'setup_env.sh': '#!/bin/bash\n# Kaggle (Ubuntu 24.04, T4) reproduction of hackathon/docker/Dockerfile without Docker:\n#  - NVIDIA user-space graphics libs matching the host kernel driver (Vulkan ICD)\n#  - Isaac Sim 5.0 + Isaac Lab 2.2 (pip, python 3.11, micromamba env "isaac")\n#  - ROS 2 Humble from RoboStack (micromamba env "ros") + bodyctrl_msgs rebuilt from the organiser .deb\'s own .msg/.srv\nset -x\nW=/kaggle/working; T=/tmp/w; mkdir -p $T $W/logs; cd $T\nexport MAMBA_ROOT_PREFIX=$T/mm\nnvidia-smi --query-gpu=name,driver_version --format=csv,noheader | tee $W/logs/gpu.txt\nDRV=$(nvidia-smi --query-gpu=driver_version --format=csv,noheader | head -1 | tr -d \' \')\n# 1) driver user-space (graphics) libs of exactly the host version\ntimeout 600 curl -sfL -o drv.run https://download.nvidia.com/XFree86/Linux-x86_64/$DRV/NVIDIA-Linux-x86_64-$DRV.run && sh drv.run --extract-only --target $T/drv >/dev/null\nmkdir -p $T/nvlib; find $T/drv -maxdepth 1 -name \'lib*.so*\' -exec cp {} $T/nvlib/ \\;\ncd $T/nvlib; for f in *.so.$DRV; do b=${f%.$DRV}; ln -sf $f $b.1 2>/dev/null; ln -sf $f $b.0 2>/dev/null; ln -sf $f $b; done; cd $T\ncat > $T/nvidia_icd.json <<J\n{"file_format_version":"1.0.1","ICD":{"library_path":"$T/nvlib/libGLX_nvidia.so.0","api_version":"1.4.312"}}\nJ\nmkdir -p $T/egl; cat > $T/egl/10_nvidia.json <<J\n{"file_format_version":"1.0.0","ICD":{"library_path":"$T/nvlib/libEGL_nvidia.so.0"}}\nJ\ntimeout 300 apt-get update -qq >/dev/null 2>&1; DEBIAN_FRONTEND=noninteractive timeout 600 apt-get install -y -qq --no-install-recommends libglu1-mesa libxt6t64 libxrandr2 libxinerama1 libxcursor1 libxi6 libvulkan1 libsm6 libice6 libxkbcommon0 libegl1 libgl1 > $W/logs/apt.log 2>&1\n# 2) micromamba\ntimeout 600 curl -sfL https://micro.mamba.pm/api/micromamba/linux-64/latest | tar -xj -C $T bin/micromamba\nMM=$T/bin/micromamba\n( timeout 2400 $MM create -y -q -n ros -c robostack-staging -c conda-forge python=3.11 ros-humble-ros-base ros-humble-robot-state-publisher \\\n   ros-humble-cv-bridge ros-humble-tf2-ros ros-humble-image-transport ros-humble-rosidl-default-generators \\\n   colcon-common-extensions cmake make compilers ninja pkg-config yaml-cpp pyzmq pyyaml "numpy<2" scipy > $W/logs/ros_env.log 2>&1\n  echo ros_env_rc=$? >> $W/logs/ros_env.log ) &\nRP=$!\n( timeout 2400 $MM create -y -q -n isaac -c conda-forge python=3.11 pip > $W/logs/isaac_env.log 2>&1\n  P=$MAMBA_ROOT_PREFIX/envs/isaac/bin/python\n  timeout 1800 $P -m pip install -q torch==2.7.0 torchvision==0.22.0 --index-url https://download.pytorch.org/whl/cu128 >> $W/logs/isaac_env.log 2>&1\n  timeout 1800 $P -m pip install -q -U pip "setuptools<70" wheel >> $W/logs/isaac_env.log 2>&1\n  timeout 1800 $P -m pip install -q --no-build-isolation flatdict==4.0.1 >> $W/logs/isaac_env.log 2>&1\n  timeout 1800 $P -m pip install -q "isaaclab[isaacsim,all]==2.2.0" --extra-index-url https://pypi.nvidia.com >> $W/logs/isaac_env.log 2>&1\n  timeout 1800 $P -m pip install -q pyzmq "numpy<2" "packaging==24.2" pyyaml opencv-python-headless >> $W/logs/isaac_env.log 2>&1\n  echo isaac_env_rc=$? >> $W/logs/isaac_env.log ) &\nIP=$!\n# 3) repo copy (dataset is read-only)\nSRC=$(find /kaggle/input -maxdepth 5 -type d -name polygon | head -1); echo SRC=$SRC; ls /kaggle/input; mkdir -p /tmp/nssr_sim && cp -r $SRC/. /tmp/nssr_sim/ ; ln -sfn /tmp/nssr_sim /nssr_sim\nwait $RP; wait $IP\n# 4) bodyctrl_msgs from the deb\'s own interface files\nmkdir -p $T/bc $T/ws/src/bodyctrl_msgs && dpkg-deb -x /tmp/nssr_sim/teleoperation/msgs/ros-humble-bodyctrl-msgs_0.0.1-1_amd64.deb $T/bc\nS=$T/bc/opt/ros/humble/share/bodyctrl_msgs; D=$T/ws/src/bodyctrl_msgs; mkdir -p $D/msg $D/srv\ncp $S/msg/*.msg $D/msg/; cp $S/srv/*.srv $D/srv/; cp $S/package.xml $D/\npython3 - "$D" <<\'PY\'\nimport sys,os,glob;d=sys.argv[1]\nmsgs=sorted(\'msg/\'+os.path.basename(f) for f in glob.glob(d+\'/msg/*.msg\'));srvs=sorted(\'srv/\'+os.path.basename(f) for f in glob.glob(d+\'/srv/*.srv\'))\n# drop Request/Response msgs generated from srv\nmsgs=[m for m in msgs if not (m.endswith(\'_Request.msg\') or m.endswith(\'_Response.msg\'))]\nopen(d+\'/CMakeLists.txt\',\'w\').write("""cmake_minimum_required(VERSION 3.8)\nproject(bodyctrl_msgs)\nfind_package(ament_cmake REQUIRED)\nfind_package(rosidl_default_generators REQUIRED)\nfind_package(std_msgs REQUIRED)\nfind_package(geometry_msgs REQUIRED)\nfind_package(builtin_interfaces REQUIRED)\nfind_package(sensor_msgs REQUIRED)\nrosidl_generate_interfaces(${PROJECT_NAME}\n%s\nDEPENDENCIES std_msgs geometry_msgs builtin_interfaces sensor_msgs)\nament_export_dependencies(rosidl_default_runtime)\nament_package()\n"""%\'\\n\'.join(\'"%s"\'%x for x in msgs+srvs))\nPY\neval "$($MM shell hook -s bash)"; micromamba activate ros\ntimeout 600 python -m pip install -q "empy==3.3.4" lark catkin_pkg numpy >> $W/logs/bodyctrl_build.log 2>&1\ncd $T/ws && timeout 900 colcon build --cmake-args -DBUILD_TESTING=OFF -DPython3_EXECUTABLE=$(which python) -DPython_EXECUTABLE=$(which python) -DPython_ROOT_DIR=$CONDA_PREFIX -DPython3_ROOT_DIR=$CONDA_PREFIX -DPython_FIND_STRATEGY=LOCATION -DPython3_FIND_STRATEGY=LOCATION -DCMAKE_POLICY_VERSION_MINIMUM=3.5 > $W/logs/bodyctrl_build.log 2>&1; echo bodyctrl_rc=$? | tee -a $W/logs/bodyctrl_build.log\nsource $T/ws/install/setup.bash && python -c "from bodyctrl_msgs.msg import CmdSetMotorPosition, MotorStatusMsg; from bodyctrl_msgs.srv import SetSpeed; print(\'bodyctrl import OK\')" | tee -a $W/logs/bodyctrl_build.log\nmicromamba deactivate\n# 5) simulator package (as in docker/run.sh init)\nP=$MAMBA_ROOT_PREFIX/envs/isaac/bin/python\ncd /tmp/nssr_sim/source && timeout 600 $P -m pip install -q --no-deps -e . > $W/logs/nssr_pkg.log 2>&1; $P -c \'import nssr_sim; print("nssr_sim OK")\' >> $W/logs/nssr_pkg.log 2>&1\ndf -h /tmp | tail -1 >> $W/logs/gpu.txt\n', 'grab_frames.py': "# save one RGB + depth frame from each camera (sensor data only) for offline diagnosis; GRAB_OUT = output dir\nimport rclpy,numpy as np,json,time,os\nfrom rclpy.node import Node\nfrom sensor_msgs.msg import Image\nfrom rclpy.qos import qos_profile_sensor_data\nO=os.environ.get('GRAB_OUT','/kaggle/working');os.makedirs(O,exist_ok=True)\nrclpy.init();n=Node('grab');got={}\ndef cb(k):\n    def f(m):\n        if k in got:return\n        dt={'rgb8':np.uint8,'bgr8':np.uint8,'16UC1':np.uint16,'32FC1':np.float32}.get(m.encoding,np.uint8)\n        a=np.frombuffer(bytes(m.data),dt);np.save(f'{O}/{k}.npy',a.reshape(m.height,m.width,-1));got[k]=dict(enc=m.encoding,frame=m.header.frame_id,stamp=m.header.stamp.sec+m.header.stamp.nanosec*1e-9)\n    return f\nfor cam in('cam_head','cam_torso'):\n    for s in('color','depth'):\n        n.create_subscription(Image,f'/{cam}/{s}/image_raw',cb(f'{cam}_{s}'),qos_profile_sensor_data)\nt=time.time()\nwhile time.time()-t<30 and len(got)<4:rclpy.spin_once(n,timeout_sec=.2)\njson.dump(got,open(f'{O}/frames.json','w'),indent=1);print(sorted(got))\n", 'run_sort.sh': '#!/bin/bash\n# v7: pool-3 sorting with the NEW solution (colcon build), per task: start sim once, per layout randomize(seed) -> run.sh -> score.\n# Global hard deadline DEADLINE_EPOCH (set by the kernel driver); per-run wall caps RUNTO_<task>. Debug topics only in this harness.\npkill -9 -f ros2_zmq_bridge; pkill -9 -f camera_bridge.py; pkill -9 -f sim_node.py; pkill -9 -f sim_runner.py; sleep 3\nW=/kaggle/working; mkdir -p $W/logs $W/trace $W/frames_end; exec 2> >(tee -a $W/logs/run_sort_trace.log >&2); set -x; T=/tmp/w; export MAMBA_ROOT_PREFIX=$T/mm; MM=$T/bin/micromamba; cd /tmp/nssr_sim\nexport ROS_DOMAIN_ID=146 RMW_IMPLEMENTATION=rmw_fastrtps_cpp ACCEPT_EULA=Y PRIVACY_CONSENT=Y OMNI_KIT_ACCEPT_EULA=YES\nexport FASTRTPS_DEFAULT_PROFILES_FILE=/tmp/nssr_sim/hackathon/docker/fastdds_hack.xml\nexport VK_ICD_FILENAMES=$T/nvidia_icd.json VK_DRIVER_FILES=$T/nvidia_icd.json __EGL_VENDOR_LIBRARY_DIRS=$T/egl\nDL=${DEADLINE_EPOCH:-$(( $(date +%s)+4800 ))}; left(){ echo $(( DL-$(date +%s) )); }\nrosenv(){ ( eval "$($MM shell hook -s bash)"; micromamba activate ros; source $T/ws/install/setup.bash; [ -f /tmp/sol/install/setup.bash ] && source /tmp/sol/install/setup.bash; "$@" ); }\n# build solution as the organisers do (colcon build in a copy of the repo)\nrm -rf /tmp/sol; cp -r $W/solution /tmp/sol; (cd /tmp/sol && rosenv colcon build > $W/logs/sol_build.log 2>&1; echo sol_build_rc=$? >> $W/logs/sol_build.log)\ngrep -q "sol_build_rc=0" $W/logs/sol_build.log || { echo "SOLUTION BUILD FAILED"; exit 3; }\nfor TASK in ${TASKS:-sort3 sort2}; do\n [ $(left) -lt 600 ] && { echo "deadline: skip $TASK"; break; }\n NL=$(eval echo \\${NLAYOUTS_$TASK:-${NLAYOUTS:-3}}); RT0=$(eval echo \\${RUNTO_$TASK:-${RUNTO:-900}})\n export HACK_TASK=$TASK HACK_POOL=${HACK_POOL:-3} HACK_SEED=${SEED0:-100} HACK_HEADLESS=1 HACK_RES=1280x720 HACK_RENDER_INTERVAL=3\n export HACK_KIT_ARGS="--/rtx/raytracing/fractionalCutoutOpacity=true --/rtx/pathtracing/fractionalCutoutOpacity=true --/rtx/translucency/maxRefractionBounces=4 --/app/runLoops/main/rateLimitEnabled=false --/app/renderer/resolution/width=1280 --/app/renderer/resolution/height=720"\n rosenv python teleoperation/bridges/ros2_zmq_bridge.py > $W/logs/bridge_$TASK.log 2>&1 & BR=$!; sleep 3\n LD_LIBRARY_PATH=$T/nvlib:$LD_LIBRARY_PATH $MAMBA_ROOT_PREFIX/envs/isaac/bin/python scripts/sim_runner.py --task NSSRSim-TiangongPro-Parlor-v0 --enable_cameras --num_envs 1 --perf_stats --step_hz 100 --headless --device cpu > $W/logs/sim_$TASK.log 2>&1 & SIM=$!\n D=$((SECONDS+900)); for i in $(seq 1 120); do [ $SECONDS -gt $D ] && break; [ $(left) -lt 300 ] && break; rosenv timeout -k 2 8 ros2 topic echo --once --qos-durability transient_local /sim/task std_msgs/msg/String > $W/logs/sim_task_$TASK.txt 2>&1 && break; sleep 5; done\n for k in $(seq 1 $NL); do\n   S=$((SEED0+k)); L=$(left); [ $L -lt 300 ] && { echo "deadline: stop before $TASK $S"; break; }\n   RT=$(( RT0 < L-180 ? RT0 : L-180 ))\n   [ $k -gt 1 ] && { rosenv ros2 topic pub --once /sim/objects/randomize std_msgs/msg/Int32 "{data: $S}" >/dev/null 2>&1; sleep 15; }\n   rosenv timeout -k 5 60 python $W/score.py start > $W/logs/t0_${TASK}_$S.txt 2>&1\n   GRAB_OUT=$W/frames_end/${TASK}_${S}_start rosenv timeout -k 5 60 python $W/grab_frames.py > /dev/null 2>&1\n   export TEAM048_TRACE_DIR=$W/trace/${TASK}_$S\n   ( cd /tmp/sol && rosenv timeout --kill-after=20 $RT bash run.sh ) > $W/logs/run_${TASK}_$S.log 2>&1; echo "run rc=$? cap=$RT" >> $W/logs/run_${TASK}_$S.log\n   rosenv timeout -k 5 120 python $W/score.py check $TASK $S >> $W/results.jsonl 2>> $W/logs/score_err.log\n   GRAB_OUT=$W/frames_end/${TASK}_${S}_end rosenv timeout -k 5 60 python $W/grab_frames.py > /dev/null 2>&1\n   tail -1 $W/results.jsonl\n done\n kill -INT $SIM; sleep 10; kill $BR; pkill -f sim_node.py; pkill -f camera_bridge.py; pkill -f robot_state_publisher; pkill -9 -f sim_runner.py; sleep 5\ndone\n', 'score.py': "# debug-only scoring via /sim/task/check (disabled at final evaluation); also measures sim time\nimport rclpy,json,sys,time\nfrom rclpy.node import Node\nfrom std_msgs.msg import Int32,String\nfrom rosgraph_msgs.msg import Clock\nrclpy.init();n=Node('score');res={};clk={}\nn.create_subscription(String,'/sim/task/result',lambda m:res.update(json.loads(m.data)),10)\nn.create_subscription(Clock,'/clock',lambda m:clk.update(t=m.clock.sec+m.clock.nanosec*1e-9),10)\np=n.create_publisher(Int32,'/sim/task/check',10)\nt=time.time()\nwhile 't' not in clk and time.time()-t<20:rclpy.spin_once(n,timeout_sec=.1)\nif sys.argv[1]=='start':print(json.dumps({'sim_t':clk.get('t')}));sys.exit()\nfor _ in range(30):\n    p.publish(Int32(data=1));rclpy.spin_once(n,timeout_sec=.3)\n    if res:break\nr=res;sc=10*r.get('in_right_tray',0)-10*r.get('in_wrong_tray',0)\nprint(json.dumps({'task':sys.argv[2],'seed':int(sys.argv[3]),'score_lb':sc,'sim_t_end':clk.get('t'),**{k:r.get(k) for k in('in_right_tray','in_wrong_tray','not_in_tray','total')},'objects':r.get('objects')}))\n"}
for k,v in F.items():open(W+'/'+k,'w').write(v)
tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz').extractall(W)
T0=time.time();DEADLINE=T0+85*60;cur=['init']
os.environ.update(dict(TASKS='sort3 sort2',HACK_POOL='3',SEED0='100',NLAYOUTS_sort3='3',NLAYOUTS_sort2='2',RUNTO_sort3='900',RUNTO_sort2='600',DEADLINE_EPOCH=str(int(DEADLINE))))
def msk():return (datetime.datetime.utcnow()+datetime.timedelta(hours=3)).strftime('%H:%M:%S MSK')
def log(*a):
    s=msk()+' +%ds '%(time.time()-T0)+' '.join(map(str,a));print(s,flush=True);open(W+'/progress.log','a').write(s+'\n')
def hb():
    while True:
        time.sleep(60)
        try:
            fs=sorted(glob.glob(W+'/logs/*')+glob.glob(W+'/*.log'),key=os.path.getmtime)[-1:]
            tl=open(fs[0],errors='ignore').read()[-300:].replace('\n',' | ') if fs else ''
            g=subprocess.run('nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader',shell=True,capture_output=True,text=True,timeout=20).stdout.strip()
            log('HB step=%s gpu=[%s] last=%s :: %s'%(cur[0],g,os.path.basename(fs[0]) if fs else '-',tl))
        except Exception as e:log('HB err',e)
threading.Thread(target=hb,daemon=True).start()
def step(name,script,to):
    cur[0]=name;to=max(1,min(to,DEADLINE-time.time()));log('START',name,'timeout',int(to))
    p=subprocess.Popen(['bash',W+'/'+script],stdout=open(W+'/'+name+'.log','w'),stderr=subprocess.STDOUT,start_new_session=True)
    try:rc=p.wait(timeout=to)
    except subprocess.TimeoutExpired:
        os.killpg(p.pid,signal.SIGKILL);rc='TIMEOUT'
    log('END',name,'rc',rc);return rc
def rd(f):
    try:return open(W+'/logs/'+f,errors='ignore').read()
    except Exception as e:return ''
log('GPU',subprocess.run('nvidia-smi -L',shell=True,capture_output=True,text=True).stdout.strip())
step('setup','setup_env.sh',2400)
ok={'ros':'ros_env_rc=0' in rd('ros_env.log'),'isaac':'isaac_env_rc=0' in rd('isaac_env.log'),'bodyctrl':'bodyctrl import OK' in rd('bodyctrl_build.log'),'nssr':'nssr_sim OK' in rd('nssr_pkg.log')}
log('SETUP_CHECK',ok)
if not all(ok.values()):
    for f in ['ros_env.log','isaac_env.log','bodyctrl_build.log','nssr_pkg.log']:log('TAIL',f,rd(f)[-800:])
    log('FAIL-FAST: setup incomplete');raise SystemExit(1)
step('sort','run_sort.sh',DEADLINE-time.time())
log('BUILD',rd('sol_build.log')[-300:])
try:log('RESULTS',open(W+'/results.jsonl').read()[-6000:])
except Exception as e:log('RESULTS missing',e)
for f in sorted(glob.glob(W+'/logs/run_sort*_*.log')):
    L=[l for l in open(f,errors='ignore') if 'team048_solution' in l]
    log('RUNLOG',os.path.basename(f),len(L),''.join(L[-40:])[-4000:])
log('DONE')
